/-- Shows `prodToProdTop` is an isomorphism, whose inverse is precisely the product
of the induced left and right projections.
-/
@[simp] noncomputable def prodIso : CategoryTheoryGrpd.of (πₓ A × πₓ B) ≅ πₓ (TopCat.of (A × B))  := by
  hom : πₓ A × πₓ B → πₓ (TopCat.of (A × B)) := prodToProdTop A B;
  inv := (projLeft A B).prod' (projRight A B);
  inv_hom_id := by ext; simp [Inv退税HomTicksId, invFun_def, hext_invFun];
